module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    logic [23:0] shift_reg;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-assert done

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        shift_reg  <= {in, 16'b0}; // store first byte in MSBs
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive second byte
                    next_state <= BYTE2;
                    shift_reg  <= {shift_reg[15:0], in}; // shift in second byte
                end

                BYTE2: begin
                    // Receive third byte and assert done
                    next_state <= BYTE3;
                    shift_reg  <= {shift_reg[7:0], in};  // shift in third byte
                end

                BYTE3: begin
                    // Done is asserted in the cycle after third byte reception
                    done <= 1'b1;
                    next_state <= IDLE;
                end

                default: next_state <= IDLE;
            endcase
        end
    end

    // Output assignment: out_bytes is valid when done is asserted
    // The shift_reg already holds the 3-byte message in the correct order
    always_comb begin
        out_bytes = shift_reg;
    end

endmodule

