Prob068_countbcd.code:
module TopModule (
    input  clk,
    input  reset,
    output ena    // 3 bits: enable for tens, hundreds, thousands
    output q      // 16 bits: BCD count value
);

    // Internal registers for the 4 BCD digits
    // q[3:0]  -> ones
    // q[7:4]  -> tens
    // q[11:8] -> hundreds
    // q[15:12] -> thousands
    reg  [3:0] ones;
    reg  [3:0] tens;
    reg  [3:0] hundreds;
    reg  [3:0] thousands;

    // enable signals for the upper three digits
    // ena[0] -> tens enable
    // ena[1] -> hundreds enable
    // ena[2] -> thousands enable
    wire ena_tens;
    wire ena_hundreds;
    wire ena_thousands;

    // BCD increment logic for a single digit
    // When enable is high, the digit increments by 1 on every clock.
    // If the digit reaches 9 (4'b1001), it wraps to 0 and asserts a carry.
    always @(posedge clk) begin
        if (reset) begin
            ones    <= 4'b0;
            tens    <= 4'b0;
            hundreds <= 4'b0;
            thousands <= 4'b0;
        end else begin
            // --- Ones digit ---
            // If ones == 9, it wraps to 0 and generates a carry to tens.
            // Otherwise, it simply increments.
            if (ones == 4'b1001) begin
                ones <= 4'b0;
            end else begin
                ones <= ones + 1;
            end

            // --- Tens digit ---
            // Increment only when ones wrapped (carry).
            if (ones == 4'b1001) begin
                if (tens == 4'b1001) begin
                    tens <= 4'b0;
                end else begin
                    tens <= tens + 1;
                end
            end else begin
                tens <= tens; // hold value
            end

            // --- Hundreds digit ---
            // Increment when tens wrapped.
            if (tens == 4'b1001) begin
                if (hundreds == 4'b1001) begin
                    hundreds <= 4'b0;
                end else begin
                    hundreds <= hundreds + 1;
                end
            end else begin
                hundreds <= hundreds; // hold value
            end

            // --- Thousands digit ---
            // Increment when hundreds wrapped.
            if (hundreds == 4'b1001) begin
                if (thousands == 4'b1001) begin
                    thousands <= 4'b0;
                end else begin
                    thousands <= thousands + 1;
                end
            end else begin
                thousands <= thousands; // hold value
            end
        end
    end

    // Assign the combined 16-bit output q
    assign q = {thousands, hundreds, tens, ones};

    // Generate the three enable signals.
    // ena[0] is asserted when the ones digit wrapped (i.e., just rolled over from 9 to 0).
    // ena[1] is asserted when the tens digit wrapped.
    // ena[2] is asserted when the hundreds digit wrapped.
    // We use the internal carry conditions to drive these.
    assign ena_tens   = (ones == 4'b1001);      // ones just rolled over
    assign ena_hundreds = (tens == 4'b1001);   // tens just rolled over
    assign ena_thousands = (hundreds == 4'b1001); // hundreds just rolled over

    // The specification requests ena as a 3-bit output.
    // We map the three enables to the three output bits.
    assign ena = {ena_thousands, ena_hundreds, ena_tens};

endmodule

