module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

// State encoding
typedef enum logic [3:0] {
    WALK_LEFT,    // 0
    WALK_RIGHT,   // 1
    FALLING,      // 2
    DIGGING,      // 3
    SPLATTERED    // 4
} state_t;

state_t state, next_state;

// Outputs (Moore machine - outputs depend only on state)
assign walk_left   = (state == WALK_LEFT);
assign walk_right  = (state == WALK_RIGHT);
assign aaah        = (state == FALLING);
assign digging     = (state == DIGGING);

// State register (positive edge triggered, async reset)
always_ff @(posedge clk or posedge areset) begin
    if (areset)
        state <= WALK_LEFT;
    else
        state <= next_state;
end

// Next-state logic
always_comb begin
    // Default: stay in current state
    next_state = state;

    case (state)
        WALK_LEFT: begin
            // Priority: fall > dig > switch direction
            if (!ground) begin
                // Falling starts immediately when ground disappears
                next_state = FALLING;
            end else if (dig) begin
                // Start digging if walking on ground
                next_state = DIGGING;
            end else if (bump_left || bump_right) begin
                // Switch direction when bumped
                // bump_left -> walk right, bump_right -> walk left
                // bumped on both -> still switch (bump_left takes precedence in assignment)
                next_state = (bump_left) ? WALK_RIGHT : WALK_LEFT;
            end
            // else stay WALK_LEFT
        end

        WALK_RIGHT: begin
            if (!ground) begin
                next_state = FALLING;
            end else if (dig) begin
                next_state = DIGGING;
            end else if (bump_left || bump_right) begin
                next_state = (bump_right) ? WALK_LEFT : WALK_RIGHT;
            end
            // else stay WALK_RIGHT
        end

        FALLING: begin
            if (ground) begin
                // Check splatter condition: fell for more than 20 clock cycles
                // If counter >= 20, splatter; else resume walking
                if (state_fall_count >= 20) begin
                    next_state = SPLATTERED;
                end else begin
                    // Ground reappears: resume walking in same direction
                    // Need to know original direction - stored in state_fall_dir
                    if (state_fall_dir == 0) // was walking left
                        next_state = WALK_LEFT;
                    else
                        next_state = WALK_RIGHT;
                end
            end else begin
                // Still falling, increment counter
                // (counter update happens in sequential block, here we just transition)
                next_state = FALLING;
            end
            // While falling: being bumped has no effect, dig has no effect
        end

        DIGGING: begin
            if (!ground) begin
                // Reached the other side, start falling
                next_state = FALLING;
            end else begin
                // Still on ground, continue digging
                // Being bumped has no effect while digging
                // Being told to dig when already digging is fine (stay digging)
                if (dig)
                    next_state = DIGGING;
                else
                    next_state = DIGGING; // continue digging until ground disappears
            end
            // While digging: being bumped has no effect
        end

        SPLATTERED: begin
            // Forever stuck, all outputs 0
            next_state = SPLATTERED;
        end
    endcase
end

// Fall duration counter
// Counts clock cycles while in FALLING state
// Changed type to state_t to resolve cast errors with comparison
logic [4:0] state_fall_count; // 5 bits enough for >20

always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
        state_fall_count <= 0;
    end else begin
        case (state)
            FALLING: begin
                // Increment counter each cycle while falling
                if (state_fall_count < 31) // max value
                    state_fall_count <= state_fall_count + 1;
                else
                    state_fall_count <= state_fall_count;
            end
            default: begin // WALK_LEFT, WALK_RIGHT, DIGGING, SPLATTERED
                state_fall_count <= 0;
            end
        endcase
    end
end

// Store direction when falling starts, to resume correctly
// Changed type to state_t to resolve cast errors with comparison
logic state_fall_dir; // 0 = left, 1 = right

always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
        state_fall_dir <= 0;
    end else begin
        case (state)
            WALK_LEFT: begin
                // If transitioning to FALLING, store direction
                if (!ground && (next_state == FALLING))
                    state_fall_dir <= 0;
            end
            WALK_RIGHT: begin
                if (!ground && (next_state == FALLING))
                    state_fall_dir <= 1;
            end
            FALLING: begin
                // Keep the direction stored
            end
            default: begin
            end
        endcase
    end
end

endmodule

