module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    reg  [2:0] s_prev;
    reg  [1:0] state; // 00: above s2, 01: between s2 and s1, 10: between s1 and s0, 11: below s0
    reg        dfr_reg;

    // Synchronize inputs
    always @(posedge clk) begin
        if (reset) begin
            s_prev <= 3'b000;
            state  <= 2'b11; // below s0
            dfr_reg <= 1'b1;
        end else begin
            s_prev <= s;
            // Determine state based on current sensors
            if (s[2]) state <= 2'b00;       // Above s[2]
            else if (s[1]) state <= 2'b01;  // Between s[2] and s[1]
            else if (s[0]) state <= 2'b10;  // Between s[1] and s[0]
            else       state <= 2'b11;      // Below s[0]

            // dfr: Supplemental flow valve opens if previous level was lower than current level
            // "Previous level lower than current" means we transitioned from a higher state index to a lower state index (e.g., 11 -> 10 -> 01 -> 00)
            // State index: 00 (highest level), 11 (lowest level)
            // Transition to lower state index means level rose.
            if ((s_prev[2] && !s[2]) || 
                (s_prev[1] && !s[1] && s[2]) || 
                (s_prev[0] && !s[0] && s[1] && s[2])) begin
                dfr_reg <= 1'b1;
            end else if (!s[2] && !s[1] && !s[0]) begin
                // Below lowest sensor, dfr stays high (max flow)
                dfr_reg <= 1'b1;
            end else begin
                dfr_reg <= 1'b0;
            end
        end
    end

    // Output assignments based on state
    assign fr0 = (state == 2'b10) || (state == 2'b11); // Between s1-s0 or below s0
    assign fr1 = (state == 2'b11);                      // Below s0
    assign fr2 = (state == 2'b11);                      // Below s0
    assign dfr = dfr_reg;

endmodule

