module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot decoded next-state signals
    wire next_S;
    wire next_S1;
    wire next_S11;
    wire next_S110;
    wire next_B0;
    wire next_B1;
    wire next_B2;
    wire next_B3;
    wire next_Count;
    wire next_Wait;

    // ============================================================
    // Next-state logic (derived by inspection from the state diagram)
    // ============================================================

    // From S: d=0 -> S, d=1 -> S1
    assign next_S  = (~d)  & (~next_S1);   // S when d=0 and not going to S1
    assign next_S1 = d     & (~next_S11);  // S1 when d=1 and not going to S11

    // From S1: d=0 -> S, d=1 -> S11
    // (Already covered by the S->S1 and S1->S11 transitions above,
    //  but we explicitly cover all rows for clarity and simulation
    //  completeness with the given encoding.)
    // Note: The specification lists S1->S for d=0 and S1->S11 for d=1.
    // The equations below implement exactly that behavior.

    // From S11: d=0 -> S110, d=1 -> S11
    assign next_S110 = (~d) & (~next_S110); // S110 when d=0 from S11
    assign next_S11  = d     & (~next_S11);  // stays in S11 if d=1

    // From S110: d=0 -> S, d=1 -> B0
    assign next_S    = (~d)  & (~next_S110); // S when d=0 from S110
    assign next_B0   = d     & (~next_S110); // B0 when d=1 from S110

    // From B0, B1, B2, B3: always go to next cycle
    // B0 always goes to B1
    assign next_B1 = 1'b1; // B0 -> B1 unconditionally per diagram

    // B1 always goes to B2
    assign next_B2 = 1'b1; // B1 -> B2

    // B2 always goes to B3
    assign next_B3 = 1'b1; // B2 -> B3

    // B3 always goes to Count
    assign next_Count = 1'b1; // B3 -> Count

    // Count: 
    // --done_counting=0--> Count (stay)
    // --done_counting=1--> Wait
    assign next_Wait = done_counting; // If done_counting=1, go to Wait

    // Wait:
    // --done=1, ack=0--> Wait (stay)
    // --done=1, ack=1--> S
    // (If done=0, behavior is not specified; assume stay in Wait or don't care.
    //  The specification says "Unless otherwise stated ... inputs are don't cares."
    //  We implement the specified transitions.)
    // To resolve the missing condition for done=0, we assume the transition
    // stays in Wait when done is 0, consistent with "don't care" handling
    // for unspecified inputs in the current state.
    assign next_S_wait = done & (~ack); // Go to S only if done=1 AND ack=1

    // ============================================================
    // Output signal assignments (One-hot inspection)
    // ============================================================

    // B3_next: Assert when next-state is B3
    assign B3_next = next_B3;

    // S_next: Assert when next-state is S
    assign S_next = next_S;

    // S1_next: Assert when next-state is S1
    assign S1_next = next_S1;

    // Count_next: Assert when next-state is Count
    assign Count_next = next_Count;

    // Wait_next: Assert when next-state is Wait
    assign Wait_next = next_Wait;

    // done: Output logic
    // From the diagram: Wait (done=1) --ack=1--> S.
    // The 'done' output is asserted when the state is Wait.
    // Using the one-hot encoding, Wait is the 10th bit (bit 9).
    // We assign 'done' based on the current state input port.
    wire current_Wait = state[9];

    assign done = current_Wait; // done is 1 when in Wait state

    // counting: Output logic
    // From diagram: Count (counting=1) --done_counting=0--> Count
    // This implies 'counting' is associated with the Count state.
    wire current_Count = state[8];

    assign counting = current_Count; // counting is 1 when in Count state

    // shift_ena: Output logic
    // From diagram: B0 (shift_ena=1), B1 (shift_ena=1), B2 (shift_ena=1), B3 (shift_ena=1)
    // 'shift_ena' is asserted in states B0, B1, B2, B3.
    // We OR the current state bits for B0, B1, B2, B3.
    wire current_B0 = state[4];
    wire current_B1 = state[5];
    wire current_B2 = state[6];
    wire current_B3 = state[7];

    assign shift_ena = current_B0 | current_B1 | current_B2 | current_B3;

endmodule
